def find(grid, target):
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == target:
                return r, c  # exits both loops
    return None

grid = [[1, 2, 3], [4, 5, 6]]
print(find(grid, 5))  # (1, 1)

