def area(width, height):
    """Return the area of a width by height rectangle."""
    return width * height

def grade(score):
    if score < 0 or score > 100:
        return "invalid"  # guard clause first
    if score >= 90:
        return "A"
    return "not A"

print(area(3, 4))  # 12
print(grade(95), grade(120))  # A invalid

def price(amount, symbol="$", decimals=2):
    return f"{symbol}{amount:.{decimals}f}"

print(price(5), price(5, decimals=0))  # $5.00 $5

def add_tag(tag, tags=None):  # None, not []
    if tags is None:
        tags = []
    tags.append(tag)
    return tags

print(add_tag("a"), add_tag("b"))  # ['a'] ['b']

def total(*args, **kwargs):
    print(args, kwargs)

total(1, 2, tax=0.2)  # (1, 2) {'tax': 0.2}

def factorial(n):
    if n <= 1:  # base case
        return 1
    return n * factorial(n - 1)  # smaller problem

def total(nums):
    if not nums:  # empty: nothing to add
        return 0
    return nums[0] + total(nums[1:])

print(factorial(5), total([4, 5, 6]))  # 120 15

